from math import erf, exp, log, sqrt


def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))


def bs_price(S, K, r, sigma, T, kind="call", q=0.0):
    """Black-Scholes price of a European option, dividend yield q."""
    if kind not in ("call", "put"):
        raise ValueError(f"kind must be 'call' or 'put', not {kind!r}")
    if T <= 0:                          # at expiry: intrinsic value
        return float(max(S - K, 0.0) if kind == "call" else max(K - S, 0.0))
    F = S * exp((r - q) * T)            # the forward
    D = exp(-r * T)                     # the discount factor
    if sigma <= 0:                      # no randomness: the forward payoff
        return D * (max(F - K, 0.0) if kind == "call" else max(K - F, 0.0))
    d1 = (log(S / K) + (r - q + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    if kind == "call":
        return S * exp(-q * T) * norm_cdf(d1) - K * D * norm_cdf(d2)
    return K * D * norm_cdf(-d2) - S * exp(-q * T) * norm_cdf(-d1)

import numpy as np
from math import exp, sqrt


def crr_price(S, K, r, sigma, T, n, kind="call", american=False, q=0.0):
    """CRR binomial price with n steps and dividend yield q."""
    dt = T / n
    u = exp(sigma * sqrt(dt))
    d = 1 / u
    p = (exp((r - q) * dt) - d) / (u - d)
    if not 0 <= p <= 1:
        raise ValueError(f"p = {p:.4f} is outside [0, 1]: use more steps")
    disc = exp(-r * dt)

    def payoff(s):
        return np.maximum(s - K, 0.0) if kind == "call" else np.maximum(K - s, 0.0)

    j = np.arange(n + 1)
    v = payoff(S * u ** j * d ** (n - j))          # the n + 1 leaves
    for i in range(n - 1, -1, -1):                 # step back to today
        v = disc * (p * v[1:] + (1 - p) * v[:-1])
        if american:                               # exercise at step i?
            j = np.arange(i + 1)
            v = np.maximum(v, payoff(S * u ** j * d ** (i - j)))
    return float(v[0])

import numpy as np
from math import exp, sqrt


def mc_price(S, K, r, sigma, T, kind="call", n_paths=100_000, seed=0,
             antithetic=True, q=0.0):
    """Monte Carlo price and standard error of a European option."""
    rng = np.random.default_rng(seed)
    m = n_paths // 2 if antithetic else n_paths    # independent samples
    if m < 2:
        raise ValueError("a standard error needs two independent samples")
    z = rng.standard_normal(m)                     # every normal in one call
    drift = (r - q - sigma ** 2 / 2) * T
    vol = sigma * sqrt(T)

    def disc_payoff(z):
        s_T = S * np.exp(drift + vol * z)
        pay = np.maximum(s_T - K, 0.0) if kind == "call" else np.maximum(K - s_T, 0.0)
        return exp(-r * T) * pay

    if antithetic:
        y = (disc_payoff(z) + disc_payoff(-z)) / 2  # one average per pair
    else:
        y = disc_payoff(z)
    return float(y.mean()), float(y.std(ddof=1) / sqrt(m))

