import pandas as pd


def flag_differences(grid, tree_tol=0.01, n_se=3.0):
    """One row per difference beyond its noise allowance, with a reason."""
    out = []
    for g in grid.to_dict("records"):
        checks = [("mc", g["mc"] - g["bs"], n_se * g["mc_se"]),
                  ("tree_eu", g["tree_eu"] - g["bs"], tree_tol)]
        for name, diff, allow in checks:
            if abs(diff) > allow:
                out.append((g["K"], g["T"], name, diff, "pricer-error"))
        prem = g["tree_am_put"] - g["tree_eu"]
        if prem < -tree_tol:                     # American below European
            out.append((g["K"], g["T"], "american", prem, "pricer-error"))
        elif prem > tree_tol:                    # real value, not noise
            out.append((g["K"], g["T"], "american", prem, "american-premium"))
    return pd.DataFrame(out, columns=["K", "T", "check", "diff", "reason"])
